export type PixelMarkProps = MarkProps;

export function PixelMark(props: PixelMarkProps) {
  const m = useMark(SPEC, props);
  // Memoised as an OBJECT, not a string: React 19 diffs dangerouslySetInnerHTML by identity, and a
  // fresh object every render would rebuild the markup and restart every animation.
  const body = useMemo(
    () => ({ __html: BODY[m.weight].replaceAll("__cmid__", `cp${m.uid}-`) }),
    [m.weight, m.uid],
  );
  return (
    <svg {...m.root}>
      <style>{STYLE}</style>
      <g className={m.live ? undefined : "cp-drift"} dangerouslySetInnerHTML={body} />
    </svg>
  );
}
